#!/usr/bin/env python3
"""Write the synchronized four-model hypothesis comparison pages."""

import csv
import json
from pathlib import Path


HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Common multi-model hypothesis pairs</title><style>
:root{font-family:Arial,sans-serif;color:#17233a;background:#f3f6fa}*{box-sizing:border-box}body{margin:0;padding:14px}h1{font-size:22px;margin:0 0 5px}h2{margin:0 0 8px}p,.muted{color:#52627a}.card,.controls{background:white;border:1px solid #ccd7e3;border-radius:8px;padding:10px}.summary{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.pill{background:#eef3f8;border-radius:6px;padding:8px 11px}.pill b{display:block;font-size:18px}.controls{display:flex;gap:8px;align-items:end;flex-wrap:wrap;position:sticky;top:0;z-index:5}.controls label{font-size:12px;font-weight:bold;display:flex;flex-direction:column;gap:3px}.controls select,.controls button{padding:6px;border:1px solid #afbed0;border-radius:5px;background:white;max-width:420px}.checks{display:flex;gap:9px;align-items:center;padding:5px 8px;border-left:1px solid #ccd7e3}.checks label{display:inline-flex;flex-direction:row;align-items:center;gap:4px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(180px,1fr));gap:10px;margin:10px 0}.metric{line-height:1.55}.layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(360px,1fr);gap:10px}.view{position:relative}.view img{width:100%;display:block}.view svg{position:absolute;inset:0;width:100%;height:100%}.bev svg{width:100%;display:block;background:#f8fafc}.legend{font-size:13px;color:#52627a;margin-bottom:7px}.gt{color:#2563eb}.uncovered{color:#db2777}.selected{color:#d97706}.alternative{color:#7c3aed}.maximum{color:#16a34a}.highfp{color:#dc2626}.comparison{margin-top:10px;overflow-x:auto}.comparison table{width:100%;border-collapse:collapse;font-size:13px}.comparison th,.comparison td{padding:7px 9px;border-bottom:1px solid #dde5ee;text-align:right}.comparison th:first-child,.comparison td:first-child{text-align:left}.comparison thead th{background:#f5f8fc}@media(max-width:1050px){.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.layout,.metrics{grid-template-columns:1fr}}
</style></head><body>
<h1>Common multi-model hypothesis comparison</h1><p>Each case is the same nuScenes GT across all four models. Switch models without changing the class, category, frame, camera, or GT.</p>
<div id="summary" class="summary"></div>
<section class="card comparison"><h2 id="counts-title"></h2><table><thead><tr><th>Model</th><th>Matched GT</th><th>Any better</th><th>Unmatched better</th><th>Better assigned elsewhere</th></tr></thead><tbody id="model-counts"></tbody></table><p class="muted">Better uses projected 2D IoU first, then 3D IoU, then center distance when both 3D IoUs are zero. Any better = unmatched better + better assigned elsewhere.</p></section>
<section id="coverage-section" class="card comparison"><h2>Pedestrian target-pointing coverage across all validation GTs</h2><table><thead><tr><th>Model</th><th>Covered GT</th><th>Coverage</th><th>Mean max score</th><th>Median max score</th></tr></thead><tbody id="coverage-counts"></tbody></table><p class="muted">For each GT, max score is the highest confidence among pedestrian predictions whose primary projected correspondence is that GT.</p></section>
<section id="fp-progression-section" class="card comparison"><h2>PETR-R50 pedestrian false-positive distribution across TP-ranking progression (4 m)</h2><table><thead><tr><th>TP progression</th><th>TP count</th><th>Total FPs</th><th>FP → pedestrian GT</th><th>FP → other class</th><th>FP → background</th></tr></thead><tbody><tr><td>0–25%</td><td>5,654</td><td>72</td><td>≈10 (13.9%)</td><td>≈32 (44.4%)</td><td>≈30 (41.7%)</td></tr><tr><td>25–50%</td><td>5,654</td><td>582</td><td>≈230 (39.5%)</td><td>≈180 (30.9%)</td><td>≈172 (29.6%)</td></tr><tr><td>50–75%</td><td>5,654</td><td>6,151</td><td><b>≈3,838 (62.4%)</b></td><td>≈1,267 (20.6%)</td><td>≈1,046 (17.0%)</td></tr><tr><td>75–90%</td><td>3,392</td><td>27,628</td><td><b>≈12,902 (46.7%)</b></td><td>≈8,565 (31.0%)</td><td>≈6,161 (22.3%)</td></tr><tr><td>90–100%</td><td>2,261</td><td>285,629</td><td>≈38,846 (13.6%)</td><td>≈117,394 (41.1%)</td><td><b>≈129,104 (45.2%)</b></td></tr><tr><td><b>All</b></td><td><b>22,615</b></td><td><b>320,062</b></td><td><b>≈55,826 (17.4%)</b></td><td><b>≈127,437 (39.8%)</b></td><td><b>≈136,799 (42.7%)</b></td></tr></tbody></table><p class="muted">FPs are grouped by the fraction of matched TPs recovered while traversing the confidence-ranked pedestrian predictions. Projection-category counts are approximate because they are reconstructed from percentages rounded to one decimal place.</p></section>
<div class="controls"><label>Target coverage<select id="target-coverage"><option value="all">All GTs</option><option value="covered">Has target-pointing prediction</option><option value="uncovered">No target-pointing prediction</option></select></label><span class="checks"><label class="uncovered"><input id="mark-uncovered" type="checkbox" checked>Mark uncovered GT in fuchsia</label></span></div>
<div class="controls"><label>Rule<select id="rule-version"><option value="3">Rule 3: geometric preference</option><option value="4">Rule 4: target correspondence</option></select></label><label>Class<select id="class"><option value="pedestrian">Pedestrian</option><option value="car">Car</option><option value="bicycle">Bicycle</option></select></label><label>Category<select id="category"><option value="alternative_exists">Alternative exists in every model</option><option value="official_tp_best">Official TP best in every model</option></select></label><label>Projection correspondence<select id="correspondence"><option value="all">All cases</option><option value="tp_nearby_alt_target">TP → nearby; alternative → target</option><option value="tp_target_alt_target">TP → target; alternative → target</option><option value="tp_nearby_alt_nearby">TP → nearby; alternative → nearby</option><option value="tp_target">TP → target</option><option value="tp_nearby">TP → nearby same class</option><option value="tp_other">TP → other/background</option><option value="alt_target">Alternative → target</option><option value="alt_nearby">Alternative → nearby same class</option><option value="alt_other">Alternative → other/background</option></select></label><label>Visibility<select id="visibility"><option value="all">All levels</option><option value="1">V1: 0–40%</option><option value="2">V2: 40–60%</option><option value="3">V3: 60–80%</option><option value="4">V4: 80–100%</option></select></label><label>Scene search<input id="scene-search" list="scene-options" placeholder="All scenes or token"><datalist id="scene-options"></datalist></label><label>Model<select id="model"></select></label><button id="prev">◀</button><label>Common case<select id="case"></select></label><button id="next">▶</button><span class="checks"><strong>Boxes:</strong><label class="gt"><input id="show-gt" type="checkbox" checked>GT</label><label class="selected"><input id="show-selected" type="checkbox" checked>Official TP</label><label class="alternative"><input id="show-alternative" type="checkbox" checked>Rule-4 alternative</label><label class="maximum"><input id="show-maximum" type="checkbox" checked>Max-confidence target</label><label class="highfp"><input id="show-highfp" type="checkbox">Higher-score other/BG FPs</label></span><span id="status"></span></div>
<div class="metrics"><section class="card metric gt"><h2>GT</h2><div id="gt-metrics"></div></section><section class="card metric selected"><h2>Official TP</h2><div id="selected-metrics"></div></section><section class="card metric alternative"><h2>Rule-4 alternative</h2><div id="alternative-metrics"></div></section><section class="card metric maximum"><h2>Max-confidence target prediction</h2><div id="maximum-metrics"></div></section></div>
<div class="layout"><section class="card"><h2>Camera projection</h2><div class="legend"><b class="gt">Blue</b> GT · <b class="selected">amber</b> official TP · <b class="alternative">purple</b> Rule-4 alternative · <b class="maximum">green</b> max-confidence target · <b class="highfp">red</b> higher-score other/background FP</div><div class="view"><img id="image"><svg id="overlay"></svg></div></section><section class="card bev"><h2>Camera-aligned BEV</h2><div class="legend">Selected camera always points up · ego fixed near bottom centre · cyan wedge = FOV · grid = 5 m.</div><svg id="bev" viewBox="0 0 800 800"></svg></section></div>
<section class="card comparison"><h2>Case statistics</h2><table><thead><tr><th>Measurement</th><th>Official TP</th><th>Alternative</th><th>Alternative − TP</th></tr></thead><tbody id="comparison"></tbody></table><p id="note" class="muted"></p></section>
<script src="model_counts.js?v=7"></script><script src="comparison_data.js?v=7"></script><script>
const $=id=>document.getElementById(id),colors={gt:'#2563eb',uncovered:'#db2777',selected:'#d97706',alternative:'#7c3aed',maximum:'#16a34a',highfp:'#dc2626'};let filtered=[];function f(x,n=3){return x==null?'—':Number(x).toFixed(n)}
Object.defineProperty(colors,'gt',{get(){const common=filtered[Number($('case')?.value)||0],slug=$('model')?.value,c=common?.models?.[slug];return c?.target_pointing_covered===false&&$('mark-uncovered')?.checked?colors.uncovered:'#2563eb'}})
function metric(m){return m?`confidence <b>${f(m.score)}</b><br>center error <b>${f(m.center_m)} m</b><br>3D IoU <b>${f(m.iou3d)}</b><br>projected 2D IoU <b>${f(m.projected_iou2d)}</b><br>radial / transverse <b>${f(m.radial_error_m)} / ${f(m.transverse_error_m)} m</b>`:'No distinct alternative for this common GT.'}
function svgLine(s,color){return `<line x1="${s[0]}" y1="${s[1]}" x2="${s[2]}" y2="${s[3]}" stroke="${color}" stroke-width="4"/>`}
function correspondenceLabel(c){const x=c.correspondence||{},name=v=>v==='target_gt'?'target':v==='other_same_class_gt'?'nearby':v==='other_class_or_background'?'other/bg':'—';return `TP ${name(x.official_tp)}${x.alternative?` · ALT ${name(x.alternative)}`:''}`}
function correspondenceMatches(c,filter){if(filter==='all')return true;const x=c.correspondence||{},tp=x.official_tp,alt=x.alternative;if(filter==='tp_nearby_alt_target')return tp==='other_same_class_gt'&&alt==='target_gt';if(filter==='tp_target_alt_target')return tp==='target_gt'&&alt==='target_gt';if(filter==='tp_nearby_alt_nearby')return tp==='other_same_class_gt'&&alt==='other_same_class_gt';if(filter==='tp_target')return tp==='target_gt';if(filter==='tp_nearby')return tp==='other_same_class_gt';if(filter==='tp_other')return tp==='other_class_or_background';if(filter==='alt_target')return alt==='target_gt';if(filter==='alt_nearby')return alt==='other_same_class_gt';if(filter==='alt_other')return alt==='other_class_or_background';return true}
function applyFilters(){const previous=filtered[Number($('case').value)||0],category=$('category').value,visibility=$('visibility').value,coverage=$('target-coverage').value,scene=$('scene-search').value.trim().toLowerCase(),slug=$('model').value,correspondence=$('correspondence').value;filtered=comparisonData.cases.filter(c=>c.category===category&&(visibility==='all'||String(c.models[slug].visibility)===visibility)&&(coverage==='all'||Boolean(c.models[slug].target_pointing_covered)===(coverage==='covered'))&&(!scene||(c.scene_token||'').toLowerCase().includes(scene))&&correspondenceMatches(c.models[slug],correspondence));$('case').innerHTML=filtered.map((c,i)=>`<option value="${i}">#${i+1} · ${c.models[slug].target_pointing_covered?'covered':'UNCOVERED'} · ${correspondenceLabel(c.models[slug])} · scene ${(c.scene_token||'unknown').slice(0,8)} · sample ${c.sample_token.slice(0,8)} · G${c.gt_index}</option>`).join('');const retained=previous?filtered.findIndex(c=>c.sample_token===previous.sample_token&&c.gt_index===previous.gt_index&&c.category===previous.category):-1;$('case').selectedIndex=retained>=0?retained:0;if(typeof renderRule4Counts==='function')renderRule4Counts();if(filtered.length)render();else{$('status').textContent='No common cases match these filters';$('overlay').innerHTML='';$('bev').innerHTML='';$('comparison').innerHTML=''}}
function renderBev(c,hasAlt){const ctx=c.bev_context,cam=ctx.camera_origin,ego=ctx.ego,flen=Math.hypot(...ctx.camera_forward),forward=ctx.camera_forward.map(v=>v/flen),side=[-forward[1],forward[0]],range=Math.max(20,ctx.gt_distance_m+10),turn=(v,a)=>[v[0]*Math.cos(a)-v[1]*Math.sin(a),v[0]*Math.sin(a)+v[1]*Math.cos(a)],left=turn(forward,ctx.camera_fov_rad/2),right=turn(forward,-ctx.camera_fov_rad/2),rayL=[cam[0]+left[0]*range,cam[1]+left[1]*range],rayR=[cam[0]+right[0]*range,cam[1]+right[1]*range],named=[['gt',c.boxes.gt,'show-gt','GT'],['selected',c.boxes.selected,'show-selected','TP'],...(hasAlt?[['alternative',c.boxes.alternative,'show-alternative','ALT']]:[]),...(c.boxes.maximum?[['maximum',c.boxes.maximum,'show-maximum','MAX']]:[])],fpNamed=$('show-highfp').checked?(c.high_conf_other_fps||[]).map((x,i)=>['highfp',x.box,'show-highfp',`F${i+1}`]):[],all=[...named,...fpNamed],world=[ego,cam,rayL,rayR,...all.flatMap(x=>x[1].bev_corners)],local=p=>{const dx=p[0]-ego[0],dy=p[1]-ego[1];return[dx*side[0]+dy*side[1],dx*forward[0]+dy*forward[1]]},locals=world.map(local),scale=Math.min(45,340/Math.max(6,...locals.map(p=>Math.abs(p[0]))),620/Math.max(12,...locals.map(p=>p[1])),90/Math.max(2,...locals.map(p=>-p[1]))),xy=p=>{const q=local(p);return[400-q[0]*scale,700-q[1]*scale]};let out='<rect width="800" height="800" fill="#f8fafc"/>';const step=5*scale;for(let x=400%step;x<=800;x+=step)out+=`<line x1="${x}" y1="0" x2="${x}" y2="800" stroke="#dde6ef"/>`;for(let y=700%step;y<=800;y+=step)out+=`<line x1="0" y1="${y}" x2="800" y2="${y}" stroke="#dde6ef"/>`;out+=`<polygon points="${[cam,rayL,rayR].map(xy).map(p=>p.join(',')).join(' ')}" fill="#06b6d4" fill-opacity=".10" stroke="#0891b2" stroke-width="2" stroke-dasharray="8 6"/>`;for(const [name,box,id,label] of all)if($(id).checked){const center=xy(box.translation);out+=`<polygon points="${box.bev_corners.map(xy).map(p=>p.join(',')).join(' ')}" fill="none" stroke="${colors[name]}" stroke-width="4"/><text x="${center[0]+7}" y="${center[1]-7}" fill="${colors[name]}" font-size="20" font-weight="bold">${label}</text>`}$('bev').innerHTML=out}
function render(){if(!filtered.length)return;const common=filtered[Number($('case').value)||0],slug=$('model').value,c=common.models[slug],hasAlt=common.category==='alternative_exists';$('show-alternative').disabled=!hasAlt;$('show-maximum').disabled=!c.boxes.maximum;$('show-highfp').disabled=!(c.high_conf_other_fps||[]).length;$('image').src=c.image;$('overlay').setAttribute('viewBox',`0 0 ${c.width} ${c.height}`);let overlay='';const named=[['gt',c.boxes.gt,'show-gt'],['selected',c.boxes.selected,'show-selected'],...(hasAlt?[['alternative',c.boxes.alternative,'show-alternative']]:[]),...(c.boxes.maximum?[['maximum',c.boxes.maximum,'show-maximum']]:[])];for(const [name,box,id] of named)if($(id).checked)for(const s of box.segments)overlay+=svgLine(s,colors[name]);if($('show-highfp').checked)for(const [i,fp] of (c.high_conf_other_fps||[]).entries())for(const s of fp.box.segments)overlay+=svgLine(s,colors.highfp);$('overlay').innerHTML=overlay;$('gt-metrics').innerHTML=`${common.sample_token.slice(0,8)} · G${common.gt_index}<br>visibility <b>V${c.visibility} (${c.visibility_percent})</b><br>camera <b>${c.camera}</b><br>correspondence <b>${correspondenceLabel(c)}</b><br>higher-score other/BG FPs <b>${(c.high_conf_other_fps||[]).length}</b> · frame last-TP score <b>${f(c.last_tp_score_in_frame)}</b>`;$('selected-metrics').innerHTML=metric(c.selected);$('alternative-metrics').innerHTML=metric(hasAlt?c.alternative:null);$('maximum-metrics').innerHTML=c.maximum?`${metric(c.maximum)}<br>status <b>${c.maximum.status}</b> · prediction <b>P${c.maximum.prediction_id}</b>`:'No target-pointing pedestrian prediction.';$('status').textContent=`${comparisonData.models.find(m=>m.slug===slug).name} · ${filtered.length} common cases`;renderBev(c,hasAlt);const rows=[['Confidence','score'],['Center error (m)','center_m'],['Absolute radial error (m)','radial_error_m',true],['Absolute transverse error (m)','transverse_error_m',true],['3D IoU','iou3d'],['Projected 2D IoU','projected_iou2d']];$('comparison').innerHTML=rows.map(([label,key,abs])=>{const a=abs?Math.abs(c.selected[key]):c.selected[key],b=hasAlt?(abs?Math.abs(c.alternative[key]):c.alternative[key]):null;return `<tr><td>${label}</td><td>${f(a)}</td><td>${f(b)}</td><td>${b==null||a==null?'—':f(b-a)}</td></tr>`}).join('');$('note').textContent=hasAlt?'Every model has a distinct Rule-4 target-corresponding alternative for this GT.':'No qualifying Rule-4 alternative exists for this GT in every model.'}
function pairPage(){const prefix=$('rule-version').value==='4'?'hypothesis_pairs_rule4_common_':'hypothesis_pairs_common_';location.href=`../${prefix}${$('class').value}/index.html`}function init(){$('rule-version').value='__RULE_VERSION__';$('class').value=comparisonData.class_name;$('model').innerHTML=comparisonData.models.map(m=>`<option value="${m.slug}">${m.name}</option>`).join('');const scenes={};for(const c of comparisonData.cases)scenes[c.scene_token]=(scenes[c.scene_token]||0)+1;$('scene-options').innerHTML=Object.entries(scenes).sort().map(([token,count])=>`<option value="${token}" label="${token.slice(0,8)} · ${count} cases"></option>`).join('');const a=comparisonData.available_counts,s=comparisonData.selected_counts;$('summary').innerHTML=`<div class="pill"><b>${s.alternative_exists}</b>alternative cases shown (${a.alternative_exists} available)</div><div class="pill"><b>${s.official_tp_best}</b>official-best cases shown (${a.official_tp_best} available)</div>`;$('class').onchange=pairPage;$('rule-version').onchange=pairPage;for(const id of ['category','visibility','correspondence','target-coverage'])$(id).onchange=applyFilters;$('scene-search').oninput=applyFilters;$('model').onchange=applyFilters;$('case').onchange=render;for(const id of ['show-gt','show-selected','show-alternative','show-maximum','show-highfp','mark-uncovered'])$(id).onchange=render;$('prev').onclick=()=>{if(!filtered.length)return;$('case').selectedIndex=($('case').selectedIndex-1+filtered.length)%filtered.length;render()};$('next').onclick=()=>{if(!filtered.length)return;$('case').selectedIndex=($('case').selectedIndex+1)%filtered.length;render()};applyFilters()}init();
</script><script>$('counts-title').textContent=comparisonData.class_name[0].toUpperCase()+comparisonData.class_name.slice(1);$('model-counts').innerHTML=modelCounts.map(r=>`<tr><td>${r.model}</td><td>${r.matched.toLocaleString()}</td><td>${r.any_better.toLocaleString()}</td><td>${r.unmatched_better.toLocaleString()}</td><td>${r.assigned_other_better.toLocaleString()}</td></tr>`).join('');if(comparisonData.class_name!=='pedestrian'||!coverageSummary.length)$('coverage-section').hidden=true;else $('coverage-counts').innerHTML=coverageSummary.map(r=>`<tr><td>${r.model}</td><td>${r.covered_gt.toLocaleString()}</td><td>${r.coverage_percent.toFixed(1)}%</td><td>${Number(r.mean_max_pointing_score).toFixed(3)}</td><td>${Number(r.median_max_pointing_score).toFixed(3)}</td></tr>`).join('');if(comparisonData.class_name!=='pedestrian')$('fp-progression-section').hidden=true;</script></body></html>'''


def main():
    base = Path(__file__).resolve().parent
    outputs = base/'outputs'
    root = outputs/'visualizations'
    model_sources = (
        ('PETR R50', 'petr_r50'),
        ('StreamPETR R50', 'streampetr_r50'),
        ('RepDETR3D EVA02-L', 'repdetr3d_eva02_l'),
        ('PETR EVA02-L epoch 16', 'petr_eva02_l_epoch16'),
    )
    found = 0
    for class_name in ('pedestrian', 'car', 'bicycle'):
        directory = root/('hypothesis_pairs_common_'+class_name)
        if not (directory/'comparison_data.js').is_file():
            continue
        counts = []
        for model_name, slug in model_sources:
            path = (outputs/'multimodel_hypothesis_analysis_4m'/slug/class_name/
                    'hypothesis/summary.json')
            summary = json.loads(path.read_text())
            different = summary['matched_gt_with_different_best_3d']
            assigned_other = summary['counts']['best_3d_already_tp_other_gt']
            counts.append({'model': model_name,
                           'matched': summary['official_matched_gt'],
                           'any_better': summary['counts']['preferred_any_better'],
                           'unmatched_better': summary['counts']['preferred_unmatched_better'],
                           'assigned_other_better': summary['counts']['preferred_assigned_other_better']})
        (directory/'model_counts.js').write_text(
            'const modelCounts='+json.dumps(counts, separators=(',', ':'))+';\n')
        coverage = []
        if class_name == 'pedestrian':
            comparison = outputs/'gt_pointing_coverage/comparison.csv'
            if comparison.is_file():
                by_slug = {slug: model_name
                           for model_name, slug in model_sources}
                with comparison.open(newline='') as handle:
                    rows = {row['model_slug']: row
                            for row in csv.DictReader(handle)
                            if row['visibility'] == 'all'}
                for _, slug in model_sources:
                    row = rows[slug]
                    coverage.append({
                            'model': by_slug[slug],
                            'covered_gt': int(row['covered_gt']),
                            'coverage_percent': float(row['coverage_percent']),
                            'mean_max_pointing_score': float(
                                row['mean_max_pointing_score']),
                            'median_max_pointing_score': float(
                                row['median_max_pointing_score']),
                            })
        with (directory/'model_counts.js').open('a') as handle:
            handle.write('const coverageSummary='+json.dumps(
                coverage, separators=(',', ':'))+';\n')
        (directory/'index.html').write_text(HTML.replace('__RULE_VERSION__', '3'))
        print(directory/'index.html')
        found += 1
    if not found:
        raise SystemExit('No prepared comparison_data.js files found')


if __name__ == '__main__':
    main()
